  // ── state ─────────────────────────────────────────────────────────────────────────────────────
  let root = null, view = 'home', P = null, pollT = 0, err = '';
  const F = { analysis: null, editMap: null, keypoints: null, storyboard: null, revisions: null, renderInfo: null };
  const local = { audioUrl: '', peaks: null, peaksFor: '', sketches: {} };
  const sel = { events: new Set(), ranges: [] }; // editor selection
  let kpSel = null;
  const pdir = () => `studio/${P.project}`;
  const savePending = {};
  function saveSoon(name, fn, ms = 500) { clearTimeout(savePending[name]); savePending[name] = setTimeout(fn, ms); }
  // ── drafts: text typed but not sent yet survives re-renders and reloads (this browser, per film) ──
