    if (live === null) throw new Error('Could not check the chat. Try again in a moment.');
    chat.streaming = live;
    if (live) { // really replying: queue the step, it starts when the turn ends (survives a reload)
      P.queued = { kind, text, at: Date.now() };
      await saveProject();
      render();
      return null;
    }
